import org.mockito.Mockito;
import org.mockito.MockitoAnnotations;

import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.when;

public class CronParserTest {
    @Mock
    private CronDefinition definition;

    private CronParser parser;

    @BeforeEach
    public void setUp() {
        MockitoAnnotations.openMocks(this);

        // Create mock field definitions for a standard cron expression (5 fields)
        List<FieldDefinition> fieldDefinitions = List.of(
            new FieldDefinition(CronFieldName.SECOND,
                FieldConstraintsBuilder.newBuilder().allowedValues("0-59").build()),
            new FieldDefinition(CronFieldName.MINUTE,
                FieldConstraintsBuilder.newBuilder().allowedValues("0-59").build()),
            new FieldDefinition(CronFieldName.HOUR,
                FieldConstraintsBuilder.newBuilder().allowedValues("0-23").build()),
            new FieldDefinition(CronFieldName.DAY_OF_MONTH,
                FieldConstraintsBuilder.newBuilder().allowedValues("1-31").build()),
            new FieldDefinition(CronFieldName.MONTH,
                FieldConstraintsBuilder.newBuilder().allowedValues("1-12").build())
        );

        when(definition.getFieldDefinitions()).thenReturn(fieldDefinitions);
        parser = new CronParser(definition);
    }

    @Test
    public void testInvalidExpressionThrowsException() {
        String invalidExpression = "* *";
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            parser.parse(invalidExpression);
        });
        String expectedMessage = "Cron expression contains 2 parts but we expect one of [5, 6]";
        assertThrows(Exception.class, () -> {
            assert exception.getMessage().contains(expectedMessage);
        });
    }
}

