        every = new Every(on, new IntegerFieldValue(HIGH));
        assertEquals(every, every.accept(spy));
        assertEquals(every, every.accept(strictSpy));

        on.accept(verify(spy, times(1)));
        on.accept(verify(strictSpy, times(1)));
    }

}

