        // Create mock FieldConstraints with required parameters
        Map<String, Integer> minValues = new HashMap<>();
        Map<Integer, Integer> maxValues = new HashMap<>();
        Set<SpecialChar> specialChars = new HashSet<>();

        FieldConstraints constraints = new FieldConstraints(
            minValues,
            maxValues,
            specialChars,
            1, // defaultDay
            1, // defaultMonth
            false // isLenient
        );

        visitor = new ValidationFieldExpressionVisitor(constraints, stringValidations);
    }

    @Test
    public void testIsDefault() {
        // Test case 1: Non-integer field value should return false
        FieldValue<?> nonIntegerFieldValue = new SpecialCharFieldValue(SpecialChar.LW);
        boolean result1 = visitor.isDefault(nonIntegerFieldValue);
        assertEquals(false, result1, "Non-integer field value should not be default");

        // Test case 2: Integer field value with -1 should return true
        FieldValue<?> defaultFieldValue = new IntegerFieldValue(-1);
        boolean result2 = visitor.isDefault(defaultFieldValue);
        assertEquals(true, result2, "Integer field value with -1 should be default");

        // Test case 3: Integer field value with other value should return false
        FieldValue<?> nonDefaultFieldValue = new IntegerFieldValue(5);
        boolean result3 = visitor.isDefault(nonDefaultFieldValue);
        assertEquals(false, result3, "Integer field value with other value should not be default");
    }
}

