        FieldExpression betweenExpression = new Between(1, 5);

        // Create a CronField with the expression
        CronField cronField = new CronField(
            CronFieldName.DAY_OF_WEEK, 
            betweenExpression,
            FieldConstraintsBuilder.instance().createConstraintsInstance()
        );

        // Initialize the generator with year 2016, month 2, and mondayDoWValue as true
        LocalDate date = LocalDate.of(2016, 2, 1);
        betweenDayOfWeekValueGenerator = new BetweenDayOfWeekValueGenerator(
            cronField,
            2016,
            2,
            WeekDay.fromLocalDate(date)
        );
    }

    @Test
    public void testGenerateCandidatesNotIncludingIntervalExtremes() {
        final int start = 1;
        final int end = 30;
        final List<Integer> expectedValues = new ArrayList<>();
        expectedValues.add(2);
        expectedValues.add(3);
        expectedValues.add(4);
