        expectedValues.add(25);
        expectedValues.add(26);
        expectedValues.add(29);

        List<Integer> generatedValues = betweenDayOfWeekValueGenerator.generateCandidatesNotIncludingIntervalExtremes(start, end);

        // Check if all expected values are present
        for (int value : expectedValues) {
            assertTrue(generatedValues.contains(value), "Value " + value + " should be present");
        }

        // Check if start and end are excluded
        assertFalse(generatedValues.contains(start), "Start value " + start + " should be excluded");
        assertFalse(generatedValues.contains(end), "End value " + end + " should be excluded");

        // Check if the list is sorted
        for (int i = 1; i < generatedValues.size(); i++) {
            assertTrue(generatedValues.get(i) > generatedValues.get(i - 1), "List should be sorted in ascending order");
        }
    }
}

